import { sleep } from './util'

const RETRYABLE = new Set([429, 502, 503, 504])

/** Charge a card, retrying transient provider errors with exponential backoff. */
export async function charge(client, request, { attempts = 4, baseMs = 250 } = {}) {
  for (let attempt = 1; ; attempt += 1) {
    const res = await client.post('/charges', request)
    if (res.ok || !RETRYABLE.has(res.status) || attempt === attempts) return res
    await sleep(baseMs * 2 ** (attempt - 1))
  }
}
